def _ext(lesson_id, vocab=(), quiz=(), terms=(), traps=(), reading=''):
    """ISC2 refresh helper: extend an existing lesson with new vocabulary, quiz items,
    key terms, common traps and extra reading paragraphs (appended after the original text)."""
    for _l in LESSONS:
        if _l['id'] == lesson_id:
            _l['vocabIds'] = list(_l['vocabIds']) + [v for v in vocab if v not in _l['vocabIds']]
            _l['quizIds'] = list(_l['quizIds']) + [v for v in quiz if v not in _l['quizIds']]
            _l['keyTerms'] = list(_l['keyTerms']) + [t for t in terms if t not in _l['keyTerms']]
            if traps:
                _ct = _l['commonTraps']
                _ct = [_ct] if isinstance(_ct, str) else list(_ct)
                _l['commonTraps'] = _ct + list(traps)
            if reading:
                _l['reading'] = _l['reading'].rstrip() + '\n\n' + reading.strip()
            return
    raise KeyError(lesson_id)


def _new_lesson(after_id, lesson):
    """ISC2 refresh helper: add a new lesson directly after an existing one."""
    for _i, _l in enumerate(LESSONS):
        if _l['id'] == after_id:
            LESSONS.insert(_i + 1, lesson)
            return
    raise KeyError(after_id)


def _rot(qid, options):
    # Deterministic rotation so the right answer is not always listed first in the data file
    # (the app also shuffles at render time).
    return (sum(ord(c) for c in qid) * 3) % len(options)


def _mcr(i, cat, question, options, correct, explanation, why=None):
    k = _rot(i, options)
    options = options[-k:] + options[:-k] if k else options
    return _mc(i, cat, question, options, (correct + k) % len(options), explanation, why)


def _msr(i, cat, question, options, correct, explanation, why=None):
    k = _rot(i, options)
    options = options[-k:] + options[:-k] if k else options
    return _ms(i, cat, question, options, sorted((c + k) % len(options) for c in correct), explanation, why)

FLASHCARDS.extend([
    # ---- Domain 5 additions: asset types, proofing, passwordless, sessions, policy enforcement, reviews, service accounts, escalation ----
    _fc('f9178', _IAM, 'Controlling access to information, systems, devices, facilities, applications and services',
        'Each asset type has its own access path. Information is protected by permissions, labels and encryption; systems by accounts, groups and administrative separation; devices by registration, device certificates and compliance checks; facilities by badges, locks and guards; applications by roles and scopes; services (APIs and machine-to-machine calls) by tokens, mutual TLS and narrow permissions.',
        'The CISSP answer is rarely one control. Combine identity, authorization and logging for every asset type and review them on a schedule.'),
    _fc('f9179', _IAM, 'Converged physical and logical access control',
        'Physical access systems (badges, readers) and logical access systems (directory, VPN, applications) can share identity data, so that one lifecycle process grants and removes both. Correlating them detects contradictions such as a VPN login from a person who is badged into the office, and removing a leaver in the directory also disables the badge.',
        'The usual flaw is two separate lists: staff lose network access on their last day but their badges keep working for months.'),
    _fc('f9180', _IAM, 'Groups and roles',
        'A group is a collection of identities used to manage access together; a role is a named set of permissions that match a job function. Assigning permissions to groups or roles rather than to individuals keeps administration consistent, easier to review and easier to revoke. Uncontrolled nesting of groups and too many narrowly different roles (role explosion) make reviews hard.',
        'Permissions granted directly to individual accounts are the first thing to look for in a review, because they escape group-based recertification.'),
    _fc('f9181', _IAM, 'Authentication, authorization and accounting (AAA)',
        'Authentication proves who a subject is, authorization decides what that subject may do, and accounting records what they did (logins, commands, resources used and time). AAA services such as RADIUS, TACACS+ and Diameter centralize all three for network access. Accounting supplies the audit trail that supports accountability and investigation.',
        'Without accounting there is no accountability: identification alone does not prove who performed an action.'),
    _fc('f9182', _IAM, 'Passwordless authentication',
        'Passwordless methods replace the shared secret with a cryptographic credential held by the user: passkeys and FIDO2 security keys, smart cards with certificates, or a device-bound key unlocked by a local biometric or PIN. Nothing reusable is sent to the server, which removes password phishing, spraying and stuffing, though account recovery and lost-device processes become the weak point.',
        'Passwordless is not the same as single factor: the key is something you have and the unlock is something you know or are.'),
    _fc('f9183', _IAM, 'MFA fatigue and phishing-resistant MFA',
        'MFA fatigue (push bombing) floods a user with approval prompts, hoping they accept one out of annoyance. Mitigations are number matching or other context in the prompt, rate limits and alerts on repeated denials, and moving privileged accounts to phishing-resistant methods such as FIDO2 or certificate-based authentication that do not rely on a user approving a message.',
        'SMS codes and simple push approvals are better than a password alone but can be intercepted, socially engineered or fatigued.'),
    _fc('f9184', _IAM, 'Session management',
        'After authentication a session token represents the user. It should be long, random and unpredictable, sent only over TLS, stored in cookies with the Secure, HttpOnly and SameSite attributes, replaced with a fresh value after login or privilege change, expired after idle and absolute timeouts, and destroyed on logout. Sensitive actions can require re-authentication.',
        'A weak or reusable session token bypasses even strong MFA, because the attacker needs only the token.'),
    _fc('f9185', _IAM, 'Session hijacking and session fixation',
        'Session hijacking steals a valid token (by XSS, network sniffing or malware) and replays it. Session fixation tricks a user into authenticating with a session identifier the attacker already knows. Defenses include TLS everywhere, HttpOnly and Secure cookies, regenerating the identifier at login, short lifetimes, and binding the session to client context where practical.',
        'If the session identifier does not change at login, fixation is possible even when the password is strong.'),
    _fc('f9186', _IAM, 'Registration, identity proofing and establishment of identity',
        'Registration creates the identity record. Identity proofing then resolves who the person is, validates their evidence (such as a passport or driver licence) with the issuer, and verifies that the applicant is the person described, in person or remotely. The strength of proofing should match the risk of what the identity will access.',
        'Weak proofing undermines everything after it: a strong authenticator bound to a fraudulent identity only protects the fraudster.'),
    _fc('f9187', _IAM, 'NIST SP 800-63-4 assurance levels: IAL, AAL and FAL',
        'Identity assurance levels (IAL1 to IAL3) measure proofing strength, with IAL3 requiring supervised, attended proofing with a biometric. Authenticator assurance levels (AAL1 to AAL3) measure authentication strength: AAL2 requires two factors and AAL3 adds phishing resistance with a hardware-protected, non-exportable key. Federation assurance levels (FAL1 to FAL3) measure how strongly assertions are protected.',
        'The three letters answer three questions: who are you (IAL), how do you log in (AAL) and how is your identity passed along (FAL). SP 800-63-4 is the current revision.'),
    _fc('f9188', _IAM, 'Credential management systems and password vaults',
        'A credential management system issues, binds, renews and revokes credentials (passwords, tokens, certificates, keys) across their lifecycle. A password vault stores secrets encrypted behind strong authentication, supports shared-account checkout with approval and logging, and rotates passwords automatically. Enterprise password managers apply the same idea to ordinary users.',
        'The vault is a high-value target: protect it with MFA, backups, access logging and a tested break-glass process.'),
    _fc('f9189', _IAM, 'Just-in-time provisioning of federated accounts',
        'With just-in-time provisioning, the service provider creates the local account the first time a user arrives with a valid assertion from the identity provider, using the attributes in the assertion. It avoids pre-creating accounts but needs a separate way to deprovision, such as SCIM or short-lived sessions, because the identity provider does not automatically delete the local account.',
        'Do not confuse this with just-in-time privileged access, which grants elevated rights for a limited time.'),
    _fc('f9190', _IAM, 'Federation deployment models: on-premises, cloud and hybrid',
        'On-premises federation runs the identity provider in the organization (for example a directory with a federation service); cloud federation uses an identity service delivered by a provider; hybrid keeps an on-premises directory and synchronizes or federates it with a cloud identity service. Hybrid models need consistent lifecycle, secured synchronization and a plan for identity provider outages.',
        'Whoever holds the identity provider holds the keys to every connected application, so protect and monitor it as critical infrastructure.'),
    _fc('f9191', _IAM, 'Policy decision and enforcement architecture (PAP, PIP, PDP, PEP)',
        'The policy administration point is where policies are written, the policy information point supplies attributes (role, device state, time), the policy decision point evaluates a request against policy and returns permit or deny, and the policy enforcement point sits in the path and applies that decision. Separating them allows consistent, centrally managed authorization.',
        'The same names appear in zero trust architecture and in attribute-based access control systems such as XACML.'),
    _fc('f9192', _IAM, 'Content-dependent and context-dependent access control',
        'Content-dependent control decides based on the data itself, for example a database view that hides rows with salary above a threshold. Context-dependent control decides using circumstances around the request, such as time of day, location, previous actions or transaction sequence. Both refine a base model such as RBAC.',
        'These extra conditions are how least privilege is applied at a finer grain than simple roles.'),
    _fc('f9193', _IAM, 'Account access reviews: users, systems and services',
        'Reviews examine user accounts (do they still need this), privileged and administrative accounts (more often, with sign-off by management), system and service accounts (who owns them and what do they touch) and shared or dormant accounts. The reviewer should be the business or system owner who understands the need, not the administrator who grants the access, and unused access is removed and the outcome recorded.',
        'Review frequency follows risk: privileged accounts monthly or quarterly, ordinary access at least annually.'),
    _fc('f9194', _IAM, 'Service account management',
        'Service accounts run applications and automation. Inventory them with a named owner and purpose, give them only the permissions required, deny interactive logon, store secrets in a vault, rotate credentials or use managed identities that rotate automatically, monitor for use outside the expected pattern and retire them when the application is retired.',
        'Service accounts are the classic orphaned, over-privileged and never-rotated accounts. They are often missed in recertification.'),
    _fc('f9195', _IAM, 'Role definition and role transition',
        'Role engineering defines roles from business processes (top-down) or by analyzing existing permissions (role mining, bottom-up), then checks them for separation of duties conflicts. When a person moves to a new role the old role is removed before or when the new one is added, so access reflects the current job rather than accumulating.',
        'Transfers are the main source of privilege creep; tie them to a formal change in the HR system and review afterwards.'),
    _fc('f9196', _IAM, 'Privilege escalation and auditing sudo',
        'Vertical privilege escalation gains higher rights (user to administrator); horizontal escalation reaches another user at the same level. On Unix-like systems, sudo lets approved users run specific commands as another account, so the sudoers file should grant narrow commands rather than unrestricted root, and every use should be logged, forwarded to central logging and reviewed.',
        'The right answer for administrators is delegated, logged elevation for the task, not shared root passwords or permanent administrator accounts.'),
    _fc('f9197', _IAM, 'Device and workload identities',
        'Devices and workloads need identities of their own: device certificates or registration in a management platform (checked for compliance before access), and workload or managed identities for software, using short-lived tokens or certificates instead of embedded passwords. These identities appear in access decisions, logs and reviews just like human ones.',
        'Machine identities typically outnumber human ones, and expired or unmanaged certificates are a common outage and security gap.'),
    _fc('f9198', _IAM, 'Credential stuffing, password spraying and lockout trade-offs',
        'Credential stuffing replays username and password pairs leaked elsewhere; password spraying tries a few common passwords against many accounts. Defenses are MFA, screening new passwords against breached lists, rate limiting and bot detection, and monitoring for failures across many accounts. Strict account lockout can itself be abused for denial of service, so progressive delays are often better.',
        'Password reuse is the root cause of stuffing, which is why unique passwords and MFA matter more than complexity rules.'),
    _fc('f9199', _IAM, 'Biometric privacy and presentation attacks',
        'Biometrics cannot be changed if stolen, so templates should be stored encrypted (ideally on the device) and kept separate from other data. Presentation attacks use photographs, masks or fake fingerprints, countered by liveness detection. Biometrics also raise privacy and consent obligations and should usually be combined with another factor.',
        'Match the biometric to the setting: accuracy (CER), user acceptance, cost and privacy all feed the decision.'),
    _fc('f9200', _IAM, 'Authenticating services and APIs',
        'Services should authenticate with short-lived credentials rather than long-lived shared secrets: mutual TLS with certificates, OAuth 2.0 client credentials with narrow scopes, or signed tokens from a trusted issuer. API keys identify an application but are weak proof of identity, so they must be stored securely, scoped, rotated and monitored.',
        'A key hard-coded in a repository is the commonest way service authentication fails.'),
    _fc('f9201', _IAM, 'Break-glass (emergency) access',
        'Break-glass accounts are tightly controlled, highly privileged accounts held for emergencies such as an identity provider outage. Their credentials are sealed or vaulted, use alerts and approvals, and are tested and rotated after each use. Their use is logged, reviewed and justified after the event.',
        'Break-glass access is an exception path; if it is used routinely, the normal privileged access design is failing.'),
    _fc('f9202', _IAM, 'Access control lists, capabilities and the access matrix',
        'An access control matrix has subjects on one axis and objects on the other. Reading a column gives an access control list (who may use this object); reading a row gives capabilities (what this subject may use). ACLs suit objects with many users, and capabilities suit subjects that hold unforgeable tokens of authority.',
        'ACLs are checked at the object, while capability systems let the subject present proof, which is the idea behind many access tokens.'),
    _fc('f9203', _IAM, 'Joiner, mover and leaver automation with directory sync and SCIM',
        'Authoritative sources such as the human resources system should trigger the lifecycle events: create accounts and assign baseline roles for joiners, adjust access for movers and disable accounts for leavers. Directory synchronization and SCIM push changes to downstream applications so that deprovisioning is fast and consistent.',
        'The measure to watch is time to deprovision. The longer a leaver account lives, the larger the risk.'),
])

